import re

def solve(env, goal):
    g = goal.lower().strip()
    obs = env.observation.lower()

    # Parse receptacles from room description
    rec_pattern = re.compile(r'\b([a-z]+) (\d+)\b')
    receptacles = []
    rec_types = set()
    for m in rec_pattern.finditer(obs):
        word, num = m.group(1), m.group(2)
        name = f"{word} {num}"
        if name not in receptacles:
            receptacles.append(name)
        rec_types.add(word)

    # Common receptacle types
    rec_types.update(['bed','drawer','dresser','garbagecan','shelf','sofa','table','desk',
                      'cabinet','fridge','microwave','sink','toilet','bathtub','window','door',
                      'counter','closet','safe','box','chest','rack','trashcan','garbage','bin',
                      'lamp','desklamp','light','coffee','machine','stove','oven','dishwasher'])

    # Parse goal words
    goal_words = re.findall(r'\b[a-z]+\b', g)
    common_words = {'the','a','an','to','in','with','on','at','from','of','for','and','or',
                    'put','examine','take','find','clean','go','use','open','close','look',
                    'turn','light','off','on','it','is','some','any','all','this','that'}

    # Determine target object
    obj_candidates = [w for w in goal_words if w not in common_words and w not in rec_types and not w.isdigit()]
    target_obj = obj_candidates[0] if obj_candidates else (goal_words[0] if goal_words else '')

    # Determine action
    if 'examine' in g:
        action = 'examine'
    elif 'clean' in g:
        action = 'clean'
    elif 'put' in g:
        action = 'put'
    elif 'take' in g:
        action = 'take'
    elif 'find' in g:
        action = 'find'
    elif 'open' in g:
        action = 'open'
    elif 'close' in g:
        action = 'close'
    elif 'turn' in g or 'use' in g:
        action = 'use'
    else:
        action = 'find'

    # Determine target receptacle
    target_rec = None
    for rt in rec_types:
        if re.search(r'\b' + re.escape(rt) + r'\b', g):
            m = re.search(r'\b' + re.escape(rt) + r' (\d+)\b', g)
            if m:
                target_rec = f"{rt} {m.group(1)}"
            else:
                for r in receptacles:
                    if r.startswith(rt + ' '):
                        target_rec = r
                        break
            if target_rec:
                break

    # Helper parsers
    def parse_location(text):
        m = re.search(r'You arrive at ([^.]+)\.', text)
        if m:
            return m.group(1).strip()
        if 'middle of a room' in text:
            return None
        return None

    def parse_objects(text):
        objs = []
        for m in re.finditer(r'\b(?:a|an) ([a-z]+) (\d+)\b', text):
            objs.append(f"{m.group(1)} {m.group(2)}")
        return objs

    steps = 0
    current_loc = parse_location(env.observation)
    holding = None
    visited = set()
    found_obj = None

    def step_cmd(cmd):
        nonlocal steps, current_loc
        if steps >= 50:
            return None
        feedback = env.step(cmd)
        steps += 1
        new_loc = parse_location(feedback)
        if new_loc is not None:
            current_loc = new_loc
        return feedback

    # Explore receptacles
    to_visit = [r for r in receptacles if r not in visited]
    # Also add sink if present and cleaning needed
    if action == 'clean':
        for r in receptacles:
            if r.startswith('sink'):
                if r not in to_visit:
                    to_visit.append(r)

    # First pass: visit receptacles, look for target object
    for rec in to_visit:
        if found_obj or holding:
            break
        if current_loc == rec:
            pass
        else:
            fb = step_cmd(f"go to {rec}")
            if fb is None:
                break
        visited.add(rec)
        # Parse objects at current location
        objs = parse_objects(env.observation)
        # Check if target object is present
        for obj in objs:
            base = obj.split()[0] if obj.split() else ''
            if base == target_obj or target_obj in obj:
                found_obj = obj
                break
        if found_obj:
            # Take it
            fb = step_cmd(f"take {found_obj} from {rec}")
            if fb and ('pick up' in fb.lower() or 'you pick up' in fb.lower()):
                holding = found_obj
            break

    # If not found, try opening containers (drawers, etc.)
    if not holding and not found_obj:
        for rec in receptacles:
            if rec in visited:
                continue
            if not (rec.startswith('drawer') or rec.startswith('cabinet') or rec.startswith('closet')):
                continue
            fb = step_cmd(f"go to {rec}")
            if fb is None:
                break
            visited.add(rec)
            step_cmd(f"open {rec}")
            objs = parse_objects(env.observation)
            for obj in objs:
                base = obj.split()[0] if obj.split() else ''
                if base == target_obj or target_obj in obj:
                    found_obj = obj
                    break
            if found_obj:
                fb = step_cmd(f"take {found_obj} from {rec}")
                if fb and ('pick up' in fb.lower() or 'you pick up' in fb.lower()):
                    holding = found_obj
                break

    # Now perform final action
    if action == 'examine':
        # Need to go to target_rec (lamp) and use it
        if holding:
            rec = target_rec if target_rec else None
            if not rec:
                # Find a desklamp/lamp in receptacles
                for r in receptacles:
                    if 'lamp' in r or 'desklamp' in r:
                        rec = r
                        break
            if rec:
                if current_loc != rec:
                    step_cmd(f"go to {rec}")
                # Use the lamp
                step_cmd(f"use {rec}")
                # If holding, maybe need to examine? The task says examine the pencil with the desklamp.
                # Usually "use desklamp" while holding pencil works.
                # Possibly need "examine pencil" after? We'll try.
                if holding:
                    step_cmd(f"examine {holding}")
    elif action == 'put':
        if holding:
            rec = target_rec
            if not rec:
                # Try to find a receptacle mentioned in goal
                for rt in rec_types:
                    if re.search(r'\b' + re.escape(rt) + r'\b', g):
                        for r in receptacles:
                            if r.startswith(rt + ' '):
                                rec = r
                                break
                        if rec:
                            break
            if rec:
                if current_loc != rec:
                    step_cmd(f"go to {rec}")
                step_cmd(f"put {holding} in {rec}")
    elif action == 'clean':
        if holding:
            # Find sink
            sink = None
            for r in receptacles:
                if r.startswith('sink'):
                    sink = r
                    break
            if sink:
                if current_loc != sink:
                    step_cmd(f"go to {sink}")
                # Try clean command
                fb = step_cmd(f"clean {holding}")
                if fb is None or 'cannot' in fb.lower():
                    # Try putting in sink then taking
                    step_cmd(f"put {holding} in {sink}")
                    step_cmd(f"take {holding} from {sink}")
            # Then put in target_rec
            rec = target_rec
            if rec:
                if current_loc != rec:
                    step_cmd(f"go to {rec}")
                step_cmd(f"put {holding} in {rec}")
    elif action == 'take':
        if holding and target_rec:
            if current_loc != target_rec:
                step_cmd(f"go to {target_rec}")
    elif action == 'find':
        # Already found; maybe just examine
        if holding:
            step_cmd(f"examine {holding}")

    return
